items.text:
`tp-table-of-contents` lists links to targets on the page and marks the one the reader has
reached. An indicator on the inline-start rail spans the active items.

```html
<div class="page">
  <article>
    <h2 id="features">Features <a href="#features">#</a></h2>
    …
  </article>
  <aside class="page-toc">
    <tp-table-of-contents>
      <tp-table-of-contents-item href="#features">Features</tp-table-of-contents-item>
      <tp-table-of-contents-item href="#playground">Playground</tp-table-of-contents-item>
      <tp-table-of-contents-item href="#bundle-size">Bundle size</tp-table-of-contents-item>
    </tp-table-of-contents>
  </aside>
</div>
```

```css
.page {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 14rem;
  align-items: start;
}
.page-toc {
  position: sticky;
  top: 1.5rem;
  max-block-size: calc(100vh - 3rem);
  overflow: auto;
}
```

The usual place is a sticky column on either side of the page, inside the same scroll container
as the content: the document, or a scroll area that acts as the page. The table of contents
finds that container from its targets, so the same markup works in both. When the list is longer
than its column, the current link is kept in view inside the column only.

`collectTargets(root, selector, options)` (from `@tweakpad/ui`) returns `{ element, id, label, depth? }` records for the elements your selector matches. It has no default selector, assigns no
ids and returns a depth only when you supply a `depth` function. Render one item per record:

```js
import { collectTargets } from '@tweakpad/ui';

const toc = document.querySelector('tp-table-of-contents');
toc.replaceChildren(
  ...collectTargets(document.querySelector('main'), 'h2, h3', {
    depth: (heading) => (heading.tagName === 'H3' ? 2 : 1),
  }).map(({ element, label, depth }) => {
    const item = document.createElement('tp-table-of-contents-item');
    item.target = element;
    item.depth = depth ?? 1;
    item.textContent = label;
    return item;
  }),
);
```

The heading selector and depth rule are the page's choice here, not the library's.

items.script:
const words = (
  'the a component page section reader scroll layout token theme surface control focus ' +
  'keyboard pointer screen value state event motion color spacing release team plan ' +
  'launch review document content target heading link list panel dialog menu button ' +
  'field form label message status update change design system library browser render ' +
  'measure observe frame offset region line edge start end view stays moves follows ' +
  'returns keeps shows reads writes builds shares uses needs makes finds every each one ' +
  'more less quickly carefully always often nearby visible current next previous shared'
).split(' ');

/** A small deterministic random source, so generated pages are stable between renders. */
function random(seed) {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let value = Math.imul(state ^ (state >>> 15), 1 | state);
    value ^= value + Math.imul(value ^ (value >>> 7), 61 | value);
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  };
}

/** Generated placeholder sentences, grouped into paragraphs. */
function generateParagraphs(seed, count, { sentences = [3, 6], length = [8, 18] } = {}) {
  const next = random(seed);
  const between = ([low, high]) => low + Math.floor(next() * (high - low + 1));
  return Array.from({ length: count }, () =>
    Array.from({ length: between(sentences) }, () => {
      const text = Array.from(
        { length: between(length) },
        () => words[Math.floor(next() * words.length)],
      ).join(' ');
      return `${text[0].toUpperCase()}${text.slice(1)}.`;
    }).join(' '),
  );
}

/** Fills every `[data-generate="count"]` inside `root` with generated paragraphs. */
function fillGeneratedText(root, seed = 1) {
  let offset = 0;
  for (const element of root.querySelectorAll('[data-generate]')) {
    offset += 1;
    const count = Number(element.getAttribute('data-generate')) || 3;
    for (const text of generateParagraphs(seed * 97 + offset, count)) {
      const paragraph = element.ownerDocument.createElement('p');
      paragraph.textContent = text;
      element.append(paragraph);
    }
    element.removeAttribute('data-generate');
  }
}

import { collectTargets } from '@tweakpad/ui';

/** Builds items from targets the page marks with `data-toc`; nothing is inferred. */
function collectItems(root) {
  const toc = root.querySelector('tp-table-of-contents[data-collect]');
  const article = root.querySelector('[data-article]');
  if (!toc || !article) return;
  const items = collectTargets(article, '[data-toc]', {
    depth: (element) => Number(element.getAttribute('data-toc')) || 1,
    label: (element) => element.getAttribute('data-toc-label') ?? element.textContent.trim(),
  }).map(({ element, label, depth }) => {
    const item = root.ownerDocument.createElement('tp-table-of-contents-item');
    item.target = element; // An element reference: these targets have no ids.
    item.depth = depth ?? 1;
    item.textContent = label;
    return item;
  });
  toc.replaceChildren(...items);
}

/** Fills generated text, builds collected items, and adds sections on request. */
export function setupTableOfContentsExample(root) {
  fillGeneratedText(root);
  collectItems(root);
  const add = root.querySelector('[data-add-section]');
  let count = 0;
  const onAdd = () => {
    count += 1;
    const section = root.ownerDocument.createElement('section');
    section.setAttribute('data-toc', '1');
    section.setAttribute('data-toc-label', `Appendix ${count}`);
    section.innerHTML = `<strong>Appendix ${count}</strong><div data-generate="3"></div>`;
    root.querySelector('[data-article]')?.append(section);
    fillGeneratedText(section, 40 + count);
    collectItems(root);
  };
  add?.addEventListener('click', onAdd);
  return () => add?.removeEventListener('click', onAdd);
}

